74	    /**
75	     * 创建草稿计划（版本 1，状态 DRAFT）。
76	     */
77	    public PlanResponse createDraft(CreatePlanRequest req) {
78	        validateOccupancyParams(req.occupancies());
79	        validateWithinOperationDay(req.occupancies(), req.opDate());
80	        String hash = hashCreate(req);
81	        Optional<PlanResponse> replay = replayIfPresent(OP_CREATE, req.requestKey(), hash);
82	        if (replay.isPresent()) {
83	            return replay.get();
84	        }
85	        try {
86	            return tx.execute(status -> {
87	                if (planRepo.findByKey(req.scheduleKey()).isPresent()) {
88	                    throw conflict("SCHEDULE_KEY_EXISTS", "scheduleKey 已存在: " + req.scheduleKey());
89	                }
90	                long now = System.currentTimeMillis();
91	                long planId = planRepo.insertPlan(req.scheduleKey(), req.opDate(), PlanStatus.DRAFT, now);
92	                planRepo.insertOccupancies(planId, toOccupancies(planId, req.occupancies()));
93	                PlanResponse response = loadPlan(req.scheduleKey());
94	                idemRepo.insert(OP_CREATE, req.requestKey(), hash, toJson(response), now);
95	                return response;
96	            });
97	        } catch (DuplicateKeyException e) {
98	            return resolveDuplicate(OP_CREATE, req.requestKey(), hash);
99	        }
100	    }
