175	    /**
176	     * 取消已发布计划：时隙立即释放，历史计划与占用保留不改写。
177	     */
178	    public PlanResponse cancel(String scheduleKey, String requestKey) {
179	        String hash = hashAction(OP_CANCEL, scheduleKey);
180	        Optional<PlanResponse> replay = replayIfPresent(OP_CANCEL, requestKey, hash);
181	        if (replay.isPresent()) {
182	            return replay.get();
183	        }
184	        try {
185	            return tx.execute(status -> {
186	                DayPlan plan = planRepo.findByKeyForUpdate(scheduleKey)
187	                        .orElseThrow(() -> notFound(scheduleKey));
188	                if (plan.status() != PlanStatus.PUBLISHED) {
189	                    throw conflict("PLAN_STATE_CONFLICT",
190	                            "仅已发布计划可取消，当前状态: " + plan.status());
191	                }
192	                long now = System.currentTimeMillis();
193	                planRepo.updateStatus(plan.id(), PlanStatus.CANCELLED, now);
194	                PlanResponse response = loadPlan(scheduleKey);
195	                idemRepo.insert(OP_CANCEL, requestKey, hash, toJson(response), now);
196	                return response;
197	            });
198	        } catch (DuplicateKeyException e) {
199	            return resolveDuplicate(OP_CANCEL, requestKey, hash);
200	        }
201	    }
