203	    /**
204	     * 原子改签：全局发布锁内校验新草稿（列车内部重叠与跨计划区段冲突，仅排除旧计划占用），
205	     * 通过后同一事务取消旧计划、发布新计划并追加不可变前后继关联。
206	     * 任一步失败整体回滚：旧计划仍发布、新计划仍草稿，版本、占用与关联均不改变。
207	     */
208	    public RescheduleResponse reschedule(String oldScheduleKey, RescheduleRequest req) {
209	        if (oldScheduleKey.equals(req.newScheduleKey())) {
210	            throw badRequest("新旧计划必须不同: " + oldScheduleKey);
211	        }
212	        String hash = hashReschedule(oldScheduleKey, req);
213	        Optional<RescheduleResponse> replay =
214	                replayIfPresent(OP_RESCHEDULE, req.requestKey(), hash, RescheduleResponse.class);
215	        if (replay.isPresent()) {
216	            return replay.get();
217	        }
218	        try {
219	            return tx.execute(status -> {
220	                planRepo.acquirePublishLock();
221	                DayPlan oldPlan = planRepo.findByKeyForUpdate(oldScheduleKey)
222	                        .orElseThrow(() -> notFound(oldScheduleKey));
223	                DayPlan newPlan = planRepo.findByKeyForUpdate(req.newScheduleKey())
224	                        .orElseThrow(() -> notFound(req.newScheduleKey()));
225	                if (oldPlan.status() != PlanStatus.PUBLISHED) {
226	                    throw conflict("PLAN_STATE_CONFLICT",
227	                            "仅已发布计划可改签，旧计划当前状态: " + oldPlan.status());
228	                }
229	                if (newPlan.status() != PlanStatus.DRAFT) {
230	                    throw conflict("PLAN_STATE_CONFLICT",
231	                            "改签新计划必须为草稿，当前状态: " + newPlan.status());
232	                }
233	                if (req.expectedOldVersion() != oldPlan.version()) {
234	                    throw conflict("VERSION_CONFLICT",
235	                            "expectedOldVersion=" + req.expectedOldVersion()
236	                                    + " 与旧计划当前版本 " + oldPlan.version() + " 不一致");
237	                }
238	                if (req.expectedNewVersion() != newPlan.version()) {
239	                    throw conflict("VERSION_CONFLICT",
240	                            "expectedNewVersion=" + req.expectedNewVersion()
241	                                    + " 与新计划当前版本 " + newPlan.version() + " 不一致");
242	                }
243	                if (!oldPlan.opDate().equals(newPlan.opDate())) {
244	                    throw conflict("OP_DATE_MISMATCH",
245	                            "新旧计划运营日必须相同: 旧=" + oldPlan.opDate() + " 新=" + newPlan.opDate());
246	                }
247	                if (planRepo.findLinkByPredecessor(oldPlan.id()).isPresent()) {
248	                    throw conflict("LINK_CONFLICT", "旧计划已存在直接后继: " + oldScheduleKey);
249	                }
250	                if (planRepo.findLinkBySuccessor(newPlan.id()).isPresent()) {
251	                    throw conflict("LINK_CONFLICT", "新计划已存在直接前驱: " + req.newScheduleKey());
252	                }
253	                List<Occupancy> occupancies = planRepo.findOccupancies(newPlan.id());
254	                List<Map<String, Object>> conflicts = new ArrayList<>();
255	                conflicts.addAll(findTrainOverlaps(req.newScheduleKey(), occupancies));
256	                // 仅排除旧计划与自身占用，第三方已发布计划照常参与冲突裁决
257	                conflicts.addAll(findSectionConflicts(newPlan, occupancies,
258	                        List.of(newPlan.id(), oldPlan.id())));
259	                if (!conflicts.isEmpty()) {
260	                    throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY, "SLOT_CONFLICT",
261	                            "新草稿存在时隙冲突，改签未生效", conflicts);
262	                }
263	                long now = System.currentTimeMillis();
264	                planRepo.updateStatus(oldPlan.id(), PlanStatus.CANCELLED, now);
265	                planRepo.updateStatus(newPlan.id(), PlanStatus.PUBLISHED, now);
266	                planRepo.insertRescheduleLink(oldPlan.id(), newPlan.id(), now);
267	                RescheduleResponse response = new RescheduleResponse(
268	                        loadPlan(oldScheduleKey), loadPlan(req.newScheduleKey()));
269	                idemRepo.insert(OP_RESCHEDULE, req.requestKey(), hash, toJson(response), now);
270	                return response;
271	            });
272	        } catch (DuplicateKeyException e) {
273	            return replayIfPresent(OP_RESCHEDULE, req.requestKey(), hash, RescheduleResponse.class)
274	                    .orElseThrow(() -> conflict("LINK_CONFLICT", "改签前后继关联冲突"));
275	        }
276	    }
