316	    /**
317	     * 按计划业务键查询明细（含历史占用），不存在返回 404。
318	     */
319	    public PlanResponse getPlan(String scheduleKey) {
320	        if (planRepo.findByKey(scheduleKey).isEmpty()) {
321	            throw notFound(scheduleKey);
322	        }
323	        return loadPlan(scheduleKey);
324	    }
