328	     */
329	    public List<PublishedSlotView> getPublishedSlots(LocalDate opDate, String sectionId) {
330	        return planRepo.findPublishedSlots(opDate, List.of(sectionId), List.of(-1L)).stream()
331	                .map(s -> new PublishedSlotView(s.scheduleKey(), s.trainNo(), s.sectionId(),
