338	    private PlanResponse loadPlan(String scheduleKey) {
339	        DayPlan plan = planRepo.findByKey(scheduleKey)
340	                .orElseThrow(() -> notFound(scheduleKey));
341	        List<OccupancyView> views = planRepo.findOccupancies(plan.id()).stream()
342	                .map(o -> new OccupancyView(o.trainNo(), o.sectionId(), o.startUtc(), o.endUtc()))
343	                .toList();
344	        return new PlanResponse(plan.scheduleKey(), plan.opDate(), plan.version(),
345	                plan.status().name(), views);
346	    }
