357	    /**
358	     * 参数级校验：结束必须晚于开始，且起止落在同一 Asia/Shanghai 日历日内。
359	     */
360	    private void validateOccupancyParams(List<OccupancyRequest> occupancies) {
361	        for (int i = 0; i < occupancies.size(); i++) {
362	            OccupancyRequest o = occupancies.get(i);
363	            if (!o.endUtc().isAfter(o.startUtc())) {
364	                throw badRequest("第 " + i + " 条占用结束时刻必须晚于开始时刻");
365	            }
366	            LocalDate startDay = o.startUtc().atZone(OPERATION_ZONE).toLocalDate();
367	            LocalDate endDay = o.endUtc().minusNanos(1).atZone(OPERATION_ZONE).toLocalDate();
368	            if (!startDay.equals(endDay)) {
369	                throw badRequest("第 " + i + " 条占用必须落在同一运营日（Asia/Shanghai）内");
370	            }
371	        }
372	    }
373	
374	    /**
375	     * 占用必须落在计划运营日内：[start, end) 完全包含于运营日 [dayStart, dayEnd)。
376	     */
377	    private void validateWithinOperationDay(List<OccupancyRequest> occupancies, LocalDate opDate) {
378	        Instant dayStart = opDate.atStartOfDay(OPERATION_ZONE).toInstant();
379	        Instant dayEnd = opDate.plusDays(1).atStartOfDay(OPERATION_ZONE).toInstant();
380	        for (int i = 0; i < occupancies.size(); i++) {
381	            OccupancyRequest o = occupancies.get(i);
382	            if (o.startUtc().isBefore(dayStart) || o.endUtc().isAfter(dayEnd)) {
383	                throw badRequest("第 " + i + " 条占用不在运营日 " + opDate + "（Asia/Shanghai）内");
384	            }
385	        }
386	    }
387	
388	    /**
389	     * 本计划内同一列车的重叠占用检测（左闭右开，相邻合法）。
390	     */
391	    private List<Map<String, Object>> findTrainOverlaps(String scheduleKey, List<Occupancy> occupancies) {
392	        List<Map<String, Object>> conflicts = new ArrayList<>();
393	        Map<String, List<Occupancy>> byTrain = new LinkedHashMap<>();
394	        for (Occupancy o : occupancies) {
395	            byTrain.computeIfAbsent(o.trainNo(), k -> new ArrayList<>()).add(o);
396	        }
397	        byTrain.forEach((trainNo, list) -> {
398	            List<Occupancy> sorted = list.stream()
399	                    .sorted(Comparator.comparing(Occupancy::startUtc)).toList();
400	            for (int i = 1; i < sorted.size(); i++) {
401	                Occupancy prev = sorted.get(i - 1);
402	                Occupancy cur = sorted.get(i);
403	                if (cur.startUtc().isBefore(prev.endUtc())) {
404	                    Map<String, Object> detail = new LinkedHashMap<>();
405	                    detail.put("type", "TRAIN_OVERLAP");
406	                    detail.put("scheduleKey", scheduleKey);
407	                    detail.put("trainNo", trainNo);
408	                    detail.put("sectionId", cur.sectionId());
409	                    detail.put("startUtc", cur.startUtc().toString());
410	                    detail.put("endUtc", cur.endUtc().toString());
411	                    conflicts.add(detail);
412	                }
413	            }
414	        });
415	        return conflicts;
416	    }
417	
418	    /**
419	     * 与其他已发布计划在同日期、同区段上的重叠检测（左闭右开，相邻合法）。
420	     *
421	     * @param excludePlanIds 检测时排除的计划 id（发布为自身；改签为新旧两个计划）
422	     */
423	    private List<Map<String, Object>> findSectionConflicts(DayPlan plan, List<Occupancy> occupancies,
424	                                                           List<Long> excludePlanIds) {
425	        List<String> sectionIds = occupancies.stream()
426	                .map(Occupancy::sectionId)
427	                .collect(java.util.stream.Collectors.toCollection(TreeSet::new))
428	                .stream().toList();
429	        List<PublishedSlot> published = planRepo.findPublishedSlots(plan.opDate(), sectionIds,
430	                excludePlanIds);
431	        List<Map<String, Object>> conflicts = new ArrayList<>();
432	        for (Occupancy o : occupancies) {
433	            for (PublishedSlot slot : published) {
434	                if (!o.sectionId().equals(slot.sectionId())) {
435	                    continue;
436	                }
437	                boolean overlap = o.startUtc().isBefore(slot.endUtc())
438	                        && slot.startUtc().isBefore(o.endUtc());
439	                if (overlap) {
440	                    Map<String, Object> detail = new LinkedHashMap<>();
441	                    detail.put("type", "SECTION_CONFLICT");
442	                    detail.put("sectionId", o.sectionId());
443	                    detail.put("scheduleKey", plan.scheduleKey());
444	                    detail.put("conflictingScheduleKey", slot.scheduleKey());
445	                    detail.put("trainNo", o.trainNo());
446	                    detail.put("startUtc", o.startUtc().toString());
447	                    detail.put("endUtc", o.endUtc().toString());
448	                    conflicts.add(detail);
449	                }
450	            }
451	        }
452	        return conflicts;
453	    }
454	
455	    /**
456	     * 幂等重放：存在记录且参数一致返回首次结果；参数不一致抛 409。
457	     */
458	    private Optional<PlanResponse> replayIfPresent(String opType, String requestKey, String hash) {
459	        return replayIfPresent(opType, requestKey, hash, PlanResponse.class);
460	    }
461	
462	    /**
463	     * 幂等重放（泛型）：存在记录且参数一致返回首次结果；参数不一致抛 409。
464	     */
465	    private <T> Optional<T> replayIfPresent(String opType, String requestKey, String hash,
466	                                            Class<T> type) {
467	        return idemRepo.find(opType, requestKey).map(record -> {
468	            if (!record.requestHash().equals(hash)) {
469	                throw conflict("IDEMPOTENT_KEY_REUSED",
470	                        "requestKey 已用于其他参数: " + requestKey);
471	            }
472	            return fromJson(record.responseJson(), type);
473	        });
474	    }
475	
476	    /**
477	     * 并发下唯一键冲突后的裁决：若为同键重放返回首次结果，否则说明 scheduleKey 冲突。
478	     */
479	    private PlanResponse resolveDuplicate(String opType, String requestKey, String hash) {
480	        return replayIfPresent(opType, requestKey, hash)
481	                .orElseThrow(() -> conflict("SCHEDULE_KEY_EXISTS", "scheduleKey 已存在"));
482	    }
483	
484	    private String hashCreate(CreatePlanRequest req) {
485	        StringBuilder sb = new StringBuilder(OP_CREATE).append('\n')
486	                .append(req.scheduleKey()).append('\n').append(req.opDate());
487	        appendOccupancies(sb, req.occupancies());
488	        return sha256(sb.toString());
489	    }
490	
491	    private String hashUpdate(String scheduleKey, UpdateOccupanciesRequest req) {
492	        StringBuilder sb = new StringBuilder(OP_UPDATE).append('\n')
493	                .append(scheduleKey).append('\n').append(req.expectedVersion());
494	        appendOccupancies(sb, req.occupancies());
495	        return sha256(sb.toString());
496	    }
497	
498	    private String hashAction(String opType, String scheduleKey) {
499	        return sha256(opType + '\n' + scheduleKey);
500	    }
501	
502	    private String hashReschedule(String oldScheduleKey, RescheduleRequest req) {
503	        return sha256(OP_RESCHEDULE + '\n' + oldScheduleKey + '\n' + req.newScheduleKey()
504	                + '\n' + req.expectedOldVersion() + '\n' + req.expectedNewVersion());
505	    }
506	
507	    private void appendOccupancies(StringBuilder sb, List<OccupancyRequest> occupancies) {
508	        for (OccupancyRequest o : occupancies) {
509	            sb.append('\n').append(o.trainNo()).append('|').append(o.sectionId()).append('|')
510	                    .append(o.startUtc().toEpochMilli()).append('|').append(o.endUtc().toEpochMilli());
511	        }
512	    }
513	
514	    private String sha256(String text) {
515	        try {
516	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
517	            byte[] hashed = digest.digest(text.getBytes(StandardCharsets.UTF_8));
518	            StringBuilder hex = new StringBuilder(hashed.length * 2);
519	            for (byte b : hashed) {
520	                hex.append(Character.forDigit((b >> 4) & 0xF, 16));
521	                hex.append(Character.forDigit(b & 0xF, 16));
522	            }
523	            return hex.toString();
524	        } catch (NoSuchAlgorithmException e) {
525	            throw new IllegalStateException(e);
526	        }
527	    }
528	
529	    private String toJson(Object response) {
530	        try {
531	            return objectMapper.writeValueAsString(response);
532	        } catch (Exception e) {
533	            throw new IllegalStateException("响应序列化失败", e);
534	        }
535	    }
536	
537	    private <T> T fromJson(String json, Class<T> type) {
538	        try {
539	            return objectMapper.readValue(json, type);
540	        } catch (Exception e) {
541	            throw new IllegalStateException("幂等响应反序列化失败", e);
542	        }
543	    }
544	
545	    private ApiException badRequest(String message) {
546	        return new ApiException(HttpStatus.BAD_REQUEST, "INVALID_ARGUMENT", message);
547	    }
548	
549	    private ApiException notFound(String scheduleKey) {
550	        return new ApiException(HttpStatus.NOT_FOUND, "PLAN_NOT_FOUND",
551	                "计划不存在: " + scheduleKey);
552	    }
553	
554	    private ApiException conflict(String code, String message) {
555	        return new ApiException(HttpStatus.CONFLICT, code, message);
556	    }
557	}
