public ActualMovementResponse enter(String scheduleKey, int seq, ActualActionRequest req) {
    String hash = hashActual(OP_ENTER, scheduleKey, seq, req);
    Optional<ActualMovementResponse> replay = replayIfPresent(OP_ENTER, req.requestId(), hash);
    if (replay.isPresent()) return replay.get();
    try {
        return tx.execute(status -> {
            planRepo.acquirePublishLock();
            DayPlan plan = planRepo.findByKeyForUpdate(scheduleKey)
                    .orElseThrow(() -> notFound(scheduleKey));
            if (plan.status() != PlanStatus.PUBLISHED) {
                throw conflict("PLAN_STATE_CONFLICT", "仅已发布计划可确认进入，当前状态: " + plan.status());
            }
            if (req.expectedVersion() != plan.version()) {
                throw conflict("VERSION_CONFLICT", ...);
            }
            OccupancyActual occ = actualRepo.findOccupancyActualForUpdate(plan.id(), seq)
                    .orElseThrow(() -> new ApiException(HttpStatus.NOT_FOUND, "OCCUPANCY_NOT_FOUND", "占用不存在: " + scheduleKey + "#" + seq));
            if (occ.actualStatus() != ActualStatus.NOT_ENTERED) {
                throw conflict("ACTUAL_STATE_CONFLICT", "占用当前实际状态不允许进入: " + occ.actualStatus());
            }
            Instant now = clock.instant();
            if (now.isBefore(occ.startUtc()) || !now.isBefore(occ.endUtc())) {
                throw conflict("OUTSIDE_SLOT_WINDOW", "服务器时刻不在占用时隙内...");
            }
            Optional<ActualLock> blocking = actualRepo.findInsideLocksBySection(occ.sectionId()).stream().findFirst();
            if (blocking.isPresent()) {
                throw new ApiException(HttpStatus.CONFLICT, "SECTION_OCCUPIED", "区段存在未退出列车: " + occ.sectionId(), details);
            }
            actualRepo.updateActualStatus(occ.id(), ActualStatus.INSIDE);
            actualRepo.insertEvent(plan.id(), occ.id(), seq, "ENTER", now.toEpochMilli(), plan.version(), req.operator(), req.requestId(), now.toEpochMilli());
            ActualMovementResponse response = new ActualMovementResponse(scheduleKey, seq, occ.trainNo(), occ.sectionId(), "INSIDE", now, plan.version());
            idemRepo.insert(OP_ENTER, req.requestId(), hash, toJson(response), now.toEpochMilli());
            return response;
        });
    } catch (DuplicateKeyException e) {
        return replayIfPresent(OP_ENTER, req.requestId(), hash)
            .orElseThrow(() -> conflict("IDEMPOTENT_KEY_REUSED", "requestId 已用于其他参数: " + req.requestId()));
    }
}
```

