package com.example.starter.plan.model;

/**
 * 占用实际状态：NOT_ENTERED 未进入（初始）；INSIDE 已进入未退出（同区段至多一条）；
 * EXITED 已退出（轨迹保留，不可再进入）。状态仅由服务端进入/退出确认推进。
 */
public enum ActualStatus {
    NOT_ENTERED,
    INSIDE,
    EXITED
}

package com.example.starter.plan.model;

import java.time.Instant;

/**
 * 计划内一条区段占用及其当前实际状态，区间左闭右开 [startUtc, endUtc)。
 *
 * @param id           主键
 * @param planId       所属计划 id
 * @param seq          计划内序号（占用号），保持提交顺序
 * @param trainNo      列车编号
 * @param sectionId    区段 ID
 * @param startUtc     占用开始时刻（含），UTC
 * @param endUtc       占用结束时刻（不含），UTC，必须晚于 startUtc
 * @param actualStatus 实际状态：NOT_ENTERED / INSIDE / EXITED
 */
public record OccupancyActual(long id, long planId, int seq, String trainNo, String sectionId,
                              Instant startUtc, Instant endUtc, ActualStatus actualStatus) {
}

package com.example.starter.plan.model;

import java.time.Instant;

/**
 * 实际进出轨迹事件，追加后不可变；计划取消不删除。
 *
 * @param id          主键
 * @param planId      所属计划 id
 * @param occupancyId 占用 id
 * @param seq         占用在计划内的序号
 * @param eventType   事件类型：ENTER 进入 / EXIT 退出
 * @param serverUtc   服务端确认时刻（UTC），由服务器时钟产生，调用方不可指定
 * @param planVersion 事件发生时原计划版本
 * @param operator    操作者，非空
 * @param requestId   全局幂等请求 id
 * @param createdAt   记录创建时刻，UTC 毫秒
 */
public record ActualEvent(long id, long planId, long occupancyId, int seq, String eventType,
                          Instant serverUtc, int planVersion, String operator, String requestId,
                          long createdAt) {
}

package com.example.starter.plan.model;

import java.time.Instant;

/**
 * 区段当前实际锁（一条 INSIDE 占用），同区段至多一条。
 *
 * @param scheduleKey 持有锁的计划业务键
 * @param seq         占用在计划内的序号
 * @param trainNo     列车编号
 * @param sectionId   区段 ID
 * @param enteredAt   实际进入时刻（服务端确认），UTC
 */
public record ActualLock(String scheduleKey, int seq, String trainNo, String sectionId,
                         Instant enteredAt) {
}

package com.example.starter.plan.config;

import java.time.Clock;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * 可注入时钟：实际进出确认的服务端时刻统一取自该 Bean，测试可替换为可控时钟。
 */
@Configuration
public class TimeConfig {

    /**
     * 生产默认使用 UTC 系统时钟。
     */
    @Bean
    public Clock clock() {
        return Clock.systemUTC();
    }
}

