     * 区段当前实际锁（INSIDE 占用）查询。
     */
    @GetMapping("/actual-locks")
    public List<ActualLockView> getActualLocks(@RequestParam @NotBlank String sectionId) {
        return service.getActualLocks(sectionId);
    }
}

